using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Collections.Generic;
using Newtonsoft.Json;
using EnusDE.Signaltechnik;

static class EditorPerformanceTests {
    static void Check(bool value,string text){if(!value)throw new Exception("FAIL: "+text);System.Console.WriteLine("PASS: "+text);}
    public static void Run(string root) {
        var tile=new PanelTile{X=1,Y=2,Rotation=3,Kind=PanelTileKind.TrainNumber,Mirror=true,Ports=7,Stem=1,Normal=2,Label="Ä test",Reference="native",BlockId="block",SecondBlock="second",AutoSegment="segment",Number="00123",Prefix="2",AutoMeters=12.5,Section=new TrackSection{Segment="s",From=10,To=20}};
        Check(JsonConvert.SerializeObject(tile)==JsonConvert.SerializeObject(tile.Clone())&&!ReferenceEquals(tile.Section,tile.Clone().Section),"fast tile clone preserves every serialized field while isolating its mutable section");
        bool detects=true;foreach(var field in typeof(PanelTile).GetFields(BindingFlags.Public|BindingFlags.Instance)){var changed=tile.Clone();object value=field.GetValue(changed);object next=field.FieldType==typeof(int)?(int)value+1:field.FieldType==typeof(bool)?!(bool)value:field.FieldType==typeof(string)?value+"x":field.FieldType==typeof(double)?(double)value+1:field.FieldType==typeof(PanelTileKind)?PanelTileKind.Signal:field.FieldType==typeof(TrackSection)?new TrackSection{Segment="other",From=0,To=1}:
            field.FieldType==typeof(AuxiliaryTarget)?new AuxiliaryTarget{Name="target",Anchor=new MarkerAnchor{Segment="s",Meters=10}}:
            field.FieldType==typeof(int?)?0:field.FieldType==typeof(Dictionary<int,string>)?new Dictionary<int,string>{{0,"block"}}:throw new Exception("new tile field needs equality coverage: "+field.Name);field.SetValue(changed,next);detects&=!tile.SameContent(changed);}
        Check(detects&&tile.SameContent(tile.Clone()),"undo comparison detects changes to every public tile field without per-tile JSON encoding");var zero=tile.Clone();zero.AutoMeters=0;var negative=zero.Clone();negative.AutoMeters=BitConverter.Int64BitsToDouble(long.MinValue);Check(!zero.SameContent(negative),"undo comparison preserves persisted signed-zero differences in floating-point values");
        var doc=new PanelDocument{WorldKey="performance",Tiles=new List<PanelTile>{tile},Areas=new List<PanelArea>{new PanelArea{Code="A",Name="Area",Desk="desk"}}};string original=JsonConvert.SerializeObject(doc);var copy=doc.Clone();copy.Tiles[0].Section.To=22;copy.Tiles[0].Label="changed";copy.Areas[0].Name="new";copy.Tiles.Add(tile.Clone());
        Check(JsonConvert.SerializeObject(doc)==original,"fast panel clone isolates tile list, nested track sections and editable areas");
        var library=new DeskLibrary{WorldKey="performance",AutoInitialized=true,Desks=new List<DeskDefinition>{new DeskDefinition{Global=true,Code="ESTW",Name="ESTW",Panel=doc}},Blocks=new Dictionary<string,TrackBlock>{{"block",new TrackBlock{Id="block",Name="Block",Path=new List<DirectedRouteSection>{new DirectedRouteSection{Section=new TrackSection{Segment="s",From=0,To=10},Reverse=true}},Guards=new List<TrackSection>{new TrackSection{Segment="g",From=0,To=10}}}}},Points=new Dictionary<string,PointAssignment>{{"point",new PointAssignment{Code="W1",Desk="desk"}}}};
        string before=JsonConvert.SerializeObject(library);var cloned=library.Clone();bool equal=JsonConvert.SerializeObject(cloned)==before;cloned.Desks[0].Panel.Tiles[0].Section.From=11;cloned.Desks[0].Code="other";cloned.Blocks["block"].Path[0].Reverse=false;cloned.Blocks["block"].Path[0].Section.To=12;cloned.Blocks["block"].Guards[0].To=15;cloned.Points["point"].Code="W2";
        Check(equal&&JsonConvert.SerializeObject(library)==before,"fast library clone preserves content and isolates every mutable nested desk, block path, guard and point assignment");
        doc.Tiles.Add(new PanelTile{X=0,Y=0,Label="Unicode Ä / \" \u2028",AutoMeters=1.23456789012345});string legacy=LegacyHash(doc);Check(PanelHistory.Hash(doc)==legacy,"streamed UTF-8 history hash exactly matches the old sorted JSON hash so existing undo files remain valid");doc.Tiles.Reverse();doc.Areas.Reverse();Check(PanelHistory.Hash(doc)==legacy,"history hash remains independent of drawing-list order");
        var large=new PanelDocument{WorldKey="large",Columns=512,Rows=100};for(int i=0;i<25000;i++)large.Tiles.Add(new PanelTile{X=i%512,Y=i/512,AutoSegment="segment",AutoMeters=12.5,Section=i<512?new TrackSection{Segment="s",From=0,To=10}:null});
        large.Clone();long start=GC.GetAllocatedBytesForCurrentThread();var largeCopy=large.Clone();long allocated=GC.GetAllocatedBytesForCurrentThread()-start;Check(largeCopy.Tiles.Count==25000&&allocated<8*1024*1024,"25000-field deep copy allocates under 8 MiB instead of roundtripping a complete JSON document");
        largeCopy.Tiles[0].Label="changed";var history=new PanelHistory(Path.Combine(root,"build","performance-history-"+Guid.NewGuid().ToString("N")),large);start=GC.GetAllocatedBytesForCurrentThread();history.Record(large,largeCopy);allocated=GC.GetAllocatedBytesForCurrentThread()-start;Check(allocated<64*1024*1024&&history.UndoCount==1,"single-field undo on 25000 fields stays below 64 MiB allocated and writes one actual delta");
        var undone=history.Target(largeCopy,false);Check(PanelHistory.Hash(undone)==PanelHistory.Hash(large)&&undone.Tiles[0].Label=="","optimized large-board undo restores the original field and compatible integrity hash");
        var options=new MarkerOptions{UseGameSpacing=false,Lateral=3,Height=.15,Scale=1.5,DefaultRightSide=false,FollowView=false};var placement=ServerPlacement.From(options);placement=JsonConvert.DeserializeObject<ServerPlacement>(JsonConvert.SerializeObject(placement));var target=new MarkerOptions();placement.Apply(target);Check(placement.Matches(target)&&target.Lateral==3&&target.Height==.15&&target.Scale==1.5&&!target.UseGameSpacing&&!target.DefaultRightSide&&!target.FollowView,"world placement policy persists distance, height, scale, side and orientation together");
        var legacyPlacement=JsonConvert.DeserializeObject<ServerPlacement>("{\"RightSide\":false,\"FollowView\":true}");target=new MarkerOptions{Lateral=4,Height=.3,Scale=2,UseGameSpacing=false};legacyPlacement.Apply(target);Check(legacyPlacement.Size==null&&target.Lateral==4&&target.Height==.3&&target.Scale==2&&!target.DefaultRightSide,"older worlds without stored dimensions retain host-local distances until explicitly saved");
        bool rejected=false;placement.Size.Height=double.NaN;try{placement.Validate();}catch(InvalidDataException){rejected=true;}Check(rejected,"invalid received world placement dimensions cannot enter the validated installation");
    }
    static string LegacyHash(PanelDocument doc){var copy=JsonConvert.DeserializeObject<PanelDocument>(JsonConvert.SerializeObject(doc));copy.Tiles=copy.Tiles.OrderBy(t=>t.Y).ThenBy(t=>t.X).ToList();copy.Areas=copy.Areas.OrderBy(a=>a.Id,StringComparer.Ordinal).ToList();return SharedDocuments.Hash(Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(copy)));}
}
